const initial=()=>({revision:1,latest:1,review:false,filter:'open',author:'Sara',threads:[{id:1,revision:1,kind:'change_request',author:'Sara',message:'Add a rollback plan before we launch.',status:'open',replies:[],resolution:null}]});
