const reportSamples={"1": "<style>:host{display:block;height:100%;overflow:auto}*{box-sizing:border-box}.report-page{font:18px/1.55 system-ui,sans-serif;margin:0;background:#f5f7fb;color:#16213a;padding:36px}.kicker{font:12px ui-monospace,monospace;letter-spacing:.1em;color:#66738e;text-transform:uppercase}h1{font-size:42px;line-height:1.06;letter-spacing:-1.5px;margin:14px 0}h2{font-size:21px;margin:0 0 8px}p{margin:8px 0}.lead{font-size:20px;color:#64708a;max-width:660px}.card{padding:24px;margin:24px 0;border-radius:12px;background:white;border:1px solid #dfe5ef}.recommended{border-top:5px solid #3159e6}.pill{display:inline-block;border-radius:4px;padding:4px 9px;background:#e9eeff;color:#3159e6;font-size:12px;font-weight:600}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid .card{margin:0}.sample{font-size:12px;color:#718099;margin-top:26px}.number{font-size:36px;color:#3159e6;font-weight:700}.rollback{border-top:5px solid #3159e6;background:#edf2ff}ul{padding-left:22px;margin:8px 0}li{margin:6px 0}</style><div class=\"report-page\"><div class=\"kicker\">Product / launch review</div><h1>Pilot launch brief</h1><p class=\"lead\">A small launch. A clear learning goal.</p><section class=\"card recommended\"><span class=\"pill\">Recommended approach</span><h2>Start with an invited pilot.</h2><p>Let a small group publish, review and revise their first report before expanding access.</p></section><div class=\"grid\"><section class=\"card\"><div class=\"number\">01</div><h2>Learn first</h2><p>Watch the first report review from start to finish.</p></section><section class=\"card\"><div class=\"number\">02</div><h2>Expand deliberately</h2><p>Invite the next group after the workflow is understood.</p></section></div><div id=\"update\"></div><p class=\"sample\">Sample report \u00b7 Fictional project \u00b7 Not customer results</p></div>", "2": "<style>:host{display:block;height:100%;overflow:auto}*{box-sizing:border-box}.report-page{font:18px/1.55 system-ui,sans-serif;margin:0;background:#f5f7fb;color:#16213a;padding:36px}.kicker{font:12px ui-monospace,monospace;letter-spacing:.1em;color:#66738e;text-transform:uppercase}h1{font-size:42px;line-height:1.06;letter-spacing:-1.5px;margin:14px 0}h2{font-size:21px;margin:0 0 8px}p{margin:8px 0}.lead{font-size:20px;color:#64708a;max-width:660px}.card{padding:24px;margin:24px 0;border-radius:12px;background:white;border:1px solid #dfe5ef}.recommended{border-top:5px solid #3159e6}.pill{display:inline-block;border-radius:4px;padding:4px 9px;background:#e9eeff;color:#3159e6;font-size:12px;font-weight:600}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid .card{margin:0}.sample{font-size:12px;color:#718099;margin-top:26px}.number{font-size:36px;color:#3159e6;font-weight:700}.rollback{border-top:5px solid #3159e6;background:#edf2ff}ul{padding-left:22px;margin:8px 0}li{margin:6px 0}</style><div class=\"report-page\"><div class=\"kicker\">Product / launch review</div><h1>Pilot launch brief</h1><p class=\"lead\">A small launch. A clear learning goal.</p><section class=\"card recommended\"><span class=\"pill\">Recommended approach</span><h2>Start with an invited pilot.</h2><p>Let a small group publish, review and revise their first report before expanding access.</p></section><div class=\"grid\"><section class=\"card\"><div class=\"number\">01</div><h2>Learn first</h2><p>Watch the first report review from start to finish.</p></section><section class=\"card\"><div class=\"number\">02</div><h2>Expand deliberately</h2><p>Invite the next group after the workflow is understood.</p></section></div><section class=\"card rollback\"><span class=\"pill\">Added after review</span><h2>Rollback plan</h2><ul><li>Pause new invitations if the pilot has issues.</li><li>Revert the onboarding changes.</li><li>Keep existing reports and links accessible.</li></ul></section><p class=\"sample\">Sample report \u00b7 Fictional project \u00b7 Not customer results</p></div>"};
const shadow=$('report').attachShadow({mode:'open'});function loadReport(number){shadow.innerHTML=reportSamples[number];}
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
function action(label,fn,cls){const b=el('button',label,cls);b.type='button';b.onclick=fn;return b;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2500);}
function closeMenus(){for(const id of ['version','more']){$(id+'-menu').hidden=true;$(id).setAttribute('aria-expanded','false');}}
function menu(id){const open=$(id+'-menu').hidden;closeMenus();$(id+'-menu').hidden=!open;$(id).setAttribute('aria-expanded',String(open));}
function setReview(open){state.review=open;const mobile=matchMedia('(max-width:600px)').matches;$('canvas').inert=mobile&&open;if(mobile&&open){$('review-panel').setAttribute('role','dialog');$('review-panel').setAttribute('aria-modal','true');}else{$('review-panel').removeAttribute('role');$('review-panel').removeAttribute('aria-modal');}$('workspace').classList.toggle('reviewing',open);$('review-panel').hidden=!open;$('review-toggle').setAttribute('aria-expanded',String(open));if(open&&matchMedia('(max-width:600px)').matches)$('close-review').focus();else if(!open)$('review-toggle').focus();}
function setRevision(number){state.revision=number;loadReport(number);$('original').href='report-v'+number+'.html';$('download').href='report-v'+number+'.html';renderHeader();renderThreads();closeMenus();}
function renderHeader(){const version=$('version');version.replaceChildren(document.createTextNode('v'+state.revision+' '),el('span',state.revision===state.latest?'Latest':'Previous'),document.createTextNode('⌄'));$('revision-notice').hidden=state.revision===state.latest;$('demo-update').disabled=state.latest===2;for(const button of document.querySelectorAll('[data-version]')){button.hidden=Number(button.dataset.version)>state.latest;button.querySelector('.version-mark').textContent=Number(button.dataset.version)===state.revision?'✓':'';}const open=state.threads.filter(t=>t.status==='open').length;$('open-count').textContent=open;$('review-count').textContent=state.threads.length;$('tab-open').setAttribute('aria-pressed',String(state.filter==='open'));$('tab-all').setAttribute('aria-pressed',String(state.filter==='all'));}
function inlineEditor(thread,kind,container){container.replaceChildren();const form=el('form',undefined,'inline-editor'),title=el('p',kind==='reply'?'Reply':'Record resolution','editor-heading'),input=el('textarea');input.rows=3;input.placeholder=kind==='reply'?'Write a reply…':'Explain the resolution…';input.maxLength=10000;input.setAttribute('aria-label',kind==='reply'?'Reply':'Resolution explanation');form.append(title,input);let check;
 if(kind==='resolve'){const label=el('label');check=el('input');check.type='checkbox';check.disabled=state.revision<thread.revision;label.append(check,document.createTextNode('Link the displayed v'+state.revision+' as the resolution'));form.append(label);}
 const actions=el('div',undefined,'compose-actions'),cancel=action('Cancel',()=>container.replaceChildren()),submit=el('button',kind==='reply'?'Send reply':'Record resolution','primary');submit.type='submit';actions.append(cancel,submit);form.append(actions);form.onsubmit=e=>{e.preventDefault();if(!input.value.trim()&&!check?.checked){toast(kind==='reply'?'Write a reply first.':'Explain the resolution or explicitly link this version.');return;}if(kind==='reply')thread.replies.push({author:state.author,actor:'human',message:input.value.trim()});else{if(input.value.trim())thread.replies.push({author:state.author,actor:'human',message:input.value.trim()});thread.status='resolved';thread.resolution=check.checked?state.revision:null;state.filter='all';}render();toast(kind==='reply'?'Reply added to the sample.':'Resolution recorded, not an approval.');};container.append(form);input.focus();}
function renderThreads(){const area=$('discussion');area.replaceChildren();const visible=state.threads.filter(t=>state.filter==='all'||t.status==='open');if(!visible.length){area.append(el('p','No open feedback. Add a question or view all activity.','empty-thread'));return;}
 for(const thread of visible){const item=el('article',undefined,'thread'),type=el('div',undefined,'thread-type'),version=el('a','Reviewed v'+thread.revision);version.href='#';version.onclick=e=>{e.preventDefault();setRevision(thread.revision);};type.append(el('span',thread.kind.replaceAll('_',' ')),version);const meta=el('div',undefined,'thread-meta');meta.append(el('strong',thread.author),el('span','· human'));item.append(type,meta,el('p',thread.message,'thread-text'));
 for(const reply of thread.replies){const block=el('div',undefined,'reply-item'),who=el('div',undefined,'thread-meta');who.append(el('strong',reply.author),el('span','· '+reply.actor));block.append(who,el('p',reply.message));item.append(block);}
 if(thread.resolution){const link=el('a','Open linked resolution · v'+thread.resolution,'resolution-link');link.href='#';link.onclick=e=>{e.preventDefault();setRevision(thread.resolution);};item.append(link);}
 const controls=el('div',undefined,'thread-actions'),editor=el('div');controls.append(action('Reply',()=>inlineEditor(thread,'reply',editor)));if(thread.status==='open')controls.append(action('Record resolution',()=>inlineEditor(thread,'resolve',editor)));else controls.append(el('span','✓ Resolved','resolved'));item.append(controls,editor);area.append(item);}
}
function render(){renderHeader();renderThreads();$('identity-name').textContent=state.author;}
function reset(){state=initial();loadReport(1);$('document-shell').style.width='100%';$('preview-current').textContent='Desktop';$('message').value='';$('message').rows=1;$('compose-actions').hidden=true;$('identity-edit').hidden=true;$('author').value=state.author;$('identity-toggle').setAttribute('aria-expanded','false');$('confirm-delete').close();$('canvas').style.visibility='visible';setReview(false);closeMenus();render();}
$('version').onclick=()=>menu('version');$('more').onclick=()=>menu('more');for(const b of document.querySelectorAll('[data-version]'))b.onclick=()=>setRevision(Number(b.dataset.version));$('review-toggle').onclick=()=>setReview(!state.review);$('close-review').onclick=()=>setReview(false);$('view-latest').onclick=()=>setRevision(2);
$('tab-open').onclick=()=>{state.filter='open';render();};$('tab-all').onclick=()=>{state.filter='all';render();};$('refresh').onclick=()=>{render();toast('Sample feedback refreshed.');};$('library').onclick=()=>toast('Prototype scope: report reader. The existing library is unchanged.');
$('share').onclick=()=>{const url=new URL(location.href);url.searchParams.set('revision',String(state.revision));if(!navigator.clipboard?.writeText){toast('Prototype link: '+url.href);return;}navigator.clipboard.writeText(url.href).then(()=>toast('Prototype link copied.')).catch(()=>toast('Prototype link: '+url.href));};
$('preview-toggle').onclick=()=>{$('preview-sizes').hidden=!$('preview-sizes').hidden;};for(const b of document.querySelectorAll('[data-width]'))b.onclick=()=>{$('document-shell').style.width=b.dataset.width;$('preview-current').textContent=b.textContent;closeMenus();};$('reload').onclick=()=>{loadReport(state.revision);closeMenus();};$('delete').onclick=()=>{closeMenus();$('confirm-delete').showModal();};$('cancel-delete').onclick=()=>$('confirm-delete').close();$('confirm-delete-button').onclick=()=>{$('confirm-delete').close();$('canvas').style.visibility='hidden';toast('Sample hidden. Reset to restore it. No data was deleted.');};
$('message').onfocus=()=>{$('message').rows=3;$('compose-actions').hidden=false;};$('new-feedback').onsubmit=e=>{e.preventDefault();const message=$('message').value.trim();if(!message)return;state.threads.push({id:Date.now(),revision:state.revision,kind:$('kind').value,author:state.author,message,status:'open',replies:[],resolution:null});state.filter='open';$('message').value='';$('message').rows=1;$('compose-actions').hidden=true;render();toast('Feedback added to the sample.');};
$('identity-toggle').onclick=()=>{const open=$('identity-edit').hidden;$('identity-edit').hidden=!open;$('identity-toggle').setAttribute('aria-expanded',String(open));if(open)$('author').focus();};$('author').onchange=()=>{state.author=$('author').value.trim()||'Owner';$('identity-name').textContent=state.author;};$('identity-info').onclick=()=>{$('identity-explanation').hidden=!$('identity-explanation').hidden;};
$('demo-update').onclick=()=>{state.latest=2;state.threads[0].replies.push({author:'Agent',actor:'agent',message:'Added a rollback plan in v2. The report link is unchanged.'});render();toast('Demo: v2 is available. The opened v1 stays pinned.');};$('demo-reset').onclick=reset;
document.addEventListener('click',e=>{if(!e.target.closest('.popover')&&!e.target.closest('#version')&&!e.target.closest('#more'))closeMenus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('version-menu').hidden||!$('more-menu').hidden){closeMenus();return;}if(state.review)setReview(false);}if(e.key==='Tab'&&state.review&&matchMedia('(max-width:600px)').matches){const nodes=[...$('review-panel').querySelectorAll('button,input,select,textarea,a')].filter(n=>!n.disabled&&n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});reset();
const requested=new URLSearchParams(location.search).get('revision');if(requested==='2'){state.latest=2;setRevision(2);}if(new URLSearchParams(location.search).get('review')==='open')setReview(true);
